import{_ as t,o,c as a,ag as s}from"./chunks/framework.DMVuHR7L.js";const p=JSON.parse('{"title":"Doc-sync rules (for agents)","description":"","frontmatter":{},"headers":[],"relativePath":"bots/doc-sync.md","filePath":"bots/doc-sync.md","lastUpdated":1778542084000}'),d={name:"bots/doc-sync.md"};function i(n,e,r,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="doc-sync-rules-for-agents" tabindex="-1">Doc-sync rules (for agents) <a class="header-anchor" href="#doc-sync-rules-for-agents" aria-label="Permalink to &quot;Doc-sync rules (for agents)&quot;">​</a></h1><blockquote><p><strong>The rule.</strong> Every PR that changes user-facing behaviour updates the matching <code>docs/features/</code> page in the same PR. PRs that ship UI changes without a docs delta will be bounced.</p></blockquote><p>This page tells you exactly what counts as &quot;user-facing behaviour&quot; and what the docs delta has to look like. Follow the checklist literally.</p><h2 id="when-does-this-apply" tabindex="-1">When does this apply? <a class="header-anchor" href="#when-does-this-apply" aria-label="Permalink to &quot;When does this apply?&quot;">​</a></h2><p>A PR is in scope if it does any of:</p><ul><li>Adds, removes, or renames a widget kind.</li><li>Adds, removes, or renames a UI control (button, toolbar item, setting, menu entry).</li><li>Changes a keyboard shortcut.</li><li>Changes the meaning of an existing field, filter, level, or preset.</li><li>Changes the empty state, the connection flow, the device-picker contents, or any topbar action.</li><li>Changes the appearance of a tile in a way that makes existing screenshots look wrong (compact-mode toggle change, palette change, significant chrome reshuffle).</li></ul><p>A PR is <strong>out of scope</strong> for doc-sync if it&#39;s a pure refactor, a performance optimisation, a test-only change, a CI / tooling tweak, or a code-comment / dead-code cleanup that doesn&#39;t show up in the UI. Touch nothing under <code>docs/features/</code> in those PRs — keep the diff focused.</p><h2 id="the-checklist" tabindex="-1">The checklist <a class="header-anchor" href="#the-checklist" aria-label="Permalink to &quot;The checklist&quot;">​</a></h2><p>For each change in scope, do the matching action:</p><table tabindex="0"><thead><tr><th>Code change</th><th>Doc action</th></tr></thead><tbody><tr><td>New widget kind <code>&lt;Kind&gt;</code></td><td>Create <code>docs/features/&lt;kind&gt;.md</code>. Add a row in <code>docs/features/index.md</code>&#39;s &quot;in this section&quot; table. Add a sidebar entry in <code>docs/.vitepress/config.ts</code> under the <code>/features/</code> group. Add a row in <code>README.md</code>&#39;s widgets table.</td></tr><tr><td>Removed widget kind</td><td>Delete <code>docs/features/&lt;kind&gt;.md</code>. Remove the index row, the sidebar entry, the README row, and any inbound links (<code>grep -r &quot;/features/&lt;kind&gt;&quot; docs/</code>).</td></tr><tr><td>Renamed widget</td><td>Move the file (<code>git mv</code>), rename the slug everywhere it appears: index table, sidebar config, README table, inbound links.</td></tr><tr><td>New UI control on widget X</td><td>Edit <code>docs/features/&lt;x&gt;.md</code>&#39;s relevant section (or add one). If the control is in the per-widget settings modal, update the <em>Per-widget settings</em> section.</td></tr><tr><td>Removed UI control</td><td>Strip the matching paragraph / table row from <code>docs/features/&lt;x&gt;.md</code>.</td></tr><tr><td>Renamed UI control</td><td>Grep <code>docs/features/</code> for the old name and update verbatim.</td></tr><tr><td>Keyboard shortcut change</td><td>Update the <em>Keyboard shortcuts</em> table on the affected feature page. The in-app <code>?</code> dialog is the source of truth — verify the table matches what <code>HelpDialog.tsx</code> ships.</td></tr><tr><td>Tile chrome / appearance change</td><td>Re-run <code>npm run docs:screenshots</code> and review the captured PNG before committing.</td></tr><tr><td>New cross-cutting setting</td><td>Edit <code>docs/features/settings.md</code>.</td></tr><tr><td>New global shortcut</td><td>Edit <code>docs/features/settings.md</code> (or wherever the shortcut is documented) <strong>and</strong> update <code>HelpDialog.tsx</code>.</td></tr></tbody></table><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><p>Run <code>npm run docs:screenshots</code> after a UI change that affects how a captured shot looks. The script:</p><ul><li>Boots the app via <code>vite preview</code>.</li><li>Drives the simulator (<code>fake data</code>) through each widget.</li><li>Writes PNGs to <code>docs/features/img/&lt;slug&gt;.png</code>.</li></ul><p>Real-device-only flows (Mirror&#39;s live frame, Files transfers, the WebUSB pairing dialog) cannot be captured by the script. If the relevant flow requires a real device, leave the existing PNG in place and flag in the PR description that a future on-device pass is owed.</p><p>Don&#39;t capture against your own device&#39;s serial / IP / personal data. The simulator&#39;s defaults are safe by design.</p><h2 id="doc-only-changes" tabindex="-1">Doc-only changes <a class="header-anchor" href="#doc-only-changes" aria-label="Permalink to &quot;Doc-only changes&quot;">​</a></h2><p>If you&#39;re only updating docs, the same lint / typecheck / build / test gates apply. The docs build (<code>npm run docs:build</code>) is part of CI; broken VitePress markdown will fail it.</p><h2 id="cross-references" tabindex="-1">Cross-references <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-references&quot;">​</a></h2><p>Inbound links between feature pages use relative paths without <code>.md</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Logcat](./logcat)</span></span>
<span class="line"><span>[Test-sync rules](../bots/test-sync)</span></span></code></pre></div><p>VitePress&#39;s <code>cleanUrls</code> is on; the <code>.md</code> suffix would 404.</p><h2 id="when-the-docs-disagree-with-the-ui" tabindex="-1">When the docs disagree with the UI <a class="header-anchor" href="#when-the-docs-disagree-with-the-ui" aria-label="Permalink to &quot;When the docs disagree with the UI&quot;">​</a></h2><p>Trust the UI. The docs are documentation <em>of</em> the behaviour, not a spec the UI must match. If you find drift while working on something unrelated:</p><ul><li>If the fix is small and obviously correct, include it in your PR with a one-line note.</li><li>If the fix is contentious or implies a behaviour question, open a separate issue or surface it to the user.</li></ul><p>Don&#39;t quietly let drift accumulate.</p>`,25)])])}const g=t(d,[["render",i]]);export{p as __pageData,g as default};
